mapper.update:
update community set
    community_content = #{communityContent},
    updated_at = #{updatedAt}
where community_no = #{communityNo}

update community set
    community_reply_count = community_reply_count + 1
where community_no = #{communityNo}

update community set
    community_reply_count = community_reply_count -1
where community_no = #{communityNo}

update community_reply set
    reply_deleted = "y",
    deleted_at = #{deletedAt}
where
    community_no = #{communityNo}
and
    reply_no = #{replyNo}

update community set
    community_deleted = "y",
    updated_at = #{updatedAt}
where
    community_no = #{communityNo}

mapper.select:
select * from community_like
where
    community_no = #{communityNo}
and
    user_no = #{userNo}

mapper.update:
update community_like
    set is_liked = #{isLiked}
where
    community_no = #{communityNo}
and
    user_no = #{userNo}

update community
set
    community_like_count = (
        select count(*)
        from community_like
        where community_no = #{communityNo}
        and is_liked = 'y'
    )
where community_no = #{communityNo}
